    fields {
        #[sharding(constant)]
        pub unbounded_log_instance: UnboundedLog::Instance::<DT>,

        #[sharding(constant)]
        pub cell_ids: Seq<CellId>,

        #[sharding(constant)]
        pub buffer_size: LogIdx,

        #[sharding(constant)]
        pub num_replicas: nat,


        #[sharding(variable)]
        pub head: LogIdx,


        #[sharding(variable)]
        pub tail: LogIdx,


        #[sharding(map)]
