        &&& self.ghost_replica@.value() == data
        &&& self.combiner@.key() == nid
        &&& self.combiner@.instance_id() == inst.id()
        &&& self.cb_combiner@.key() == nid
        &&& self.cb_combiner@.instance_id() == cb_inst.id()
        &&& self.request_ids@.len() <= MAX_REQUESTS
    }

